{"command":"cat <<'EOF' > count_tokens.go
package main

import (
	"fmt"
	"go/scanner"
	"go/token"
	"os"
)

func main() {
	src, err := os.ReadFile("testdata/file1.go")
	if err != nil {
		panic(err)
	}

	fset := token.NewFileSet()
	file := fset.AddFile("testdata/file1.go", fset.Base(), len(src))
	var s scanner.Scanner
	s.Init(file, src, nil, scanner.ScanComments)

	count := 0
	for {
		_, tok, lit, _ := s.Scan()
		if tok == token.EOF {
			break
		}
		if tok == token.COMMENT {
			continue
		}
		fmt.Printf("%d: %s (%q)\n", count, tok, lit)
		count++
	}
	fmt.Println("Total:", count)
}
EOF
go run count_tokens.go
"}

