{"command":"cat <<'EOF' > count_ast.go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

func main() {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "testdata/file1.go", nil, 0)
	if err != nil {
		panic(err)
	}
	count := 0
	ast.Inspect(f, func(n ast.Node) bool {
		if n != nil {
			count++
			fmt.Printf("%T\n", n)
		}
		return true
	})
	fmt.Println("Total AST nodes:", count)
}
EOF
go run count_ast.go
"}

