{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"html"
	"io/fs"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
)

var (
	filesFlag    = flag.Bool("files", false, "read file names from stdin one at each line")
	htmlFlag     = flag.Bool("html", false, "output the results as HTML, including duplicate code fragments")
	plumbingFlag = flag.Bool("plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
	threshold    = flag.Int("t", 15, "minimum token sequence size as a clone (default 15)")
	_            = flag.Int("threshold", 15, "minimum token sequence size as a clone (default 15)")
	vendorFlag   = flag.Bool("vendor", false, "check files in vendor directory")
	verboseFlag  = flag.Bool("v", false, "explain what is being done")
	_            = flag.Bool("verbose", false, "explain what is being done")
)

type Token struct {
	Type int
	Pos  token.Pos
	End  token.Pos
	File string
	Fset *token.FileSet
}

type Clone struct {
	File  string
	Start int
	End   int
}

func main() {
	flag.Parse()

	paths := []string{}
	if *filesFlag {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			paths = append(paths, scanner.Text())
		}
	} else {
		args := flag.Args()
		if len(args) == 0 {
			args = []string{"."}
		}
		for _, arg := range args {
			info, err := os.Stat(arg)
			if err != nil {
				continue
			}
			if !info.IsDir() {
				paths = append(paths, arg)
				continue
			}
			filepath.Walk(arg, func(path string, info fs.FileInfo, err error) error {
				if err != nil {
					return nil
				}
				if !info.IsDir() && strings.HasSuffix(path, ".go") {
					if !*vendorFlag && strings.Contains(path, "vendor/") {
						return nil
					}
					paths = append(paths, path)
				}
				return nil
			})
		}
	}

	var S []Token
	typeMap := make(map[string]int)
	typeCount := 1

	for _, path := range paths {
		fset := token.NewFileSet()
