		L := groupL[seqStr]
		var cg CloneGroup
		for i := range set {
			startLine := 99999999
			endLine := 0
			for k := 0; k < L; k++ {
				pos := S[i+k].Fset.Position(S[i+k].Pos).Line
				end := S[i+k].Fset.Position(S[i+k].End).Line
				if pos < startLine {
					startLine = pos
				}
				if end > endLine {
					endLine = end
				}
			}
