			if cg.Clones[i].File != cg.Clones[j].File {
				return cg.Clones[i].File < cg.Clones[j].File
			}
			return cg.Clones[i].Start < cg.Clones[j].Start
		})
		cg.ID = seqStr
		allGroups = append(allGroups, cg)
	}

	sort.Slice(allGroups, func(i, j int) bool {
		return groupL[allGroups[i].ID] > groupL[allGroups[j].ID]
	})

	if *plumbingFlag {
		for _, cg := range allGroups {
			for i, c := range cg.Clones {
				next := cg.Clones[(i+1)%len(cg.Clones)]
				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n", c.File, c.Start, c.End, next.File, next.Start, next.End)
			}
		}
	} else if !*htmlFlag {
		for _, cg := range allGroups {
			fmt.Printf("found %d clones:\n", len(cg.Clones))
			for _, c := range cg.Clones {
				fmt.Printf("  %s:%d,%d\n", c.File, c.Start, c.End)
			}
		}
		if len(allGroups) > 0 {
			fmt.Println()
		}
		fmt.Printf("Found total %d clone groups.\n", len(allGroups))
	} else {
		// HTML output placeholder
	}
}
